const date=(v:string)=>v?new Intl.DateTimeFormat('mn-MN',{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit',timeZone:'Asia/Ulaanbaatar'}).format(new Date(v)):'—';
const initials=(name:string)=>(name||'?').split(' ').map(w=>w[0]).slice(0,2).join('');
