 const notify=useCallback((s:string)=>{setToast(s);window.setTimeout(()=>setToast(''),5000)},[]);
 useEffect(()=>{request('auth/me').then(r=>{setUser(r.user);setDemo(!r.user);setConfigured(r.configured)}).catch(()=>notify('Сервертэй холбогдож чадсангүй. Туршилтын орчин харагдаж байна.')).finally(()=>setReady(true));const p=new URLSearchParams(window.location.search);if(p.get('view')==='channels')setView('channels');if(p.get('notice'))notify(p.get('notice')!);if(p.get('pending'))setPending(p.get('pending')!);if(p.get('invite'))setAuth('register')},[notify]);
