 const refresh=useCallback(async()=>{if(demo)return;setBusy(true);const jobs=[load('accounts')];if(view==='overview')jobs.push(...['conversations','automations','posts','contacts','events','analytics'].map(r=>load(r)));if(view==='inbox')jobs.push(load('conversations'));if(view==='automations')jobs.push(load('automations'));if(view==='contacts')jobs.push(load('contacts'));if(view==='publishing')jobs.push(load('posts'));if(view==='media')jobs.push(load('media'));if(view==='analytics')jobs.push(load('analytics',{from:new Date(Date.now()-Number(range)*86400000).toISOString().slice(0,10),to:new Date().toISOString().slice(0,10)}),load('exports'));if(view==='team')jobs.push(load('team'));if(view==='settings')jobs.push(load('settings'),load('audit'));if(view==='studio')jobs.push(load('settings'));await Promise.all(jobs);setBusy(false)},[demo,view,range,load]);
 useEffect(()=>{if(ready)void refresh()},[ready,refresh]);
