 const doAction=async(action:string,payload:Row={})=>{
  if(demo){let result:Row=action==='post.validate'?{valid:true,message:'Туршилтын шалгалт. Бодит API validation хийгдээгүй.'}:{ok:true};setSample(old=>{const next={...old};const uid='demo-'+Date.now();if(action==='automation.create')next.automations=[{...automationPayload(payload as any),id:uid,status:'active',fired_count:0,sent_count:0,failed_count:0},...old.automations];if(action==='automation.update')next.automations=old.automations.map((r:Row)=>r.id===payload.id?{...r,...payload}:r);if(action==='automation.delete')next.automations=old.automations.filter((r:Row)=>r.id!==payload.id);if(action==='contact.save')next.contacts=payload.id?old.contacts.map((r:Row)=>r.id===payload.id?payload:r):[{...payload,id:uid},...old.contacts];if(action==='contact.delete')next.contacts=old.contacts.filter((r:Row)=>r.id!==payload.id);if(action==='message.send'){next.messages=[...old.messages,{id:uid,conversation_id:payload.conversation_id,direction:'outgoing',text:[payload.text,...(payload.links||[]).map((l:Row)=>l.title+': '+l.url)].filter(Boolean).join('\n'),attachments:payload.attachments||[],created_at:new Date().toISOString()}];next.conversations=old.conversations.map((r:Row)=>r.id===payload.conversation_id?{...r,last_message:payload.text}:r)}if(action==='conversation.status')next.conversations=old.conversations.filter((r:Row)=>r.id!==payload.id);if(action==='conversation.read')next.conversations=old.conversations.map((r:Row)=>r.id===payload.id?{...r,unread_count:0}:r);if(action==='post.create')next.posts=[{...payload,id:uid,status:payload.publish_now?'published':payload.scheduled_at?'scheduled':'draft'},...old.posts];if(action==='post.delete')next.posts=old.posts.filter((r:Row)=>r.id!==payload.id);if(action==='post.publish')next.posts=old.posts.map((r:Row)=>r.id===payload.id?{...r,status:'published'}:r);if(action==='post.update')next.posts=old.posts.map((r:Row)=>r.id===payload.id?{...r,...payload}:r);if(action==='post.validate')result={valid:true,message:'Туршилтын шалгалт. Бодит API validation хийгдээгүй.'};return next});notify('Туршилтын орчинд хадгаллаа. Бодит сувгаар илгээгээгүй.');return result;}
  const result=await request('action',{method:'POST',body:JSON.stringify({action,payload})});notify('Үйлдэл амжилттай.');await refresh();return result;
 };
